<?php
namespace App\Services\Selection; use App\Models\{BattingOrder,BowlingAssignment,MatchSquad,PlayingXi}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class PlayingXiService { public function __construct(private readonly SelectionEligibilityService $eligibility,private readonly SelectionAuditService $audit){} public function saveDraft(MatchSquad $ms,array $players,int $actor):MatchSquad{$allowed=$ms->players()->pluck('player_id')->map(fn($v)=>(int)$v)->all();foreach($players as $i)if(!in_array((int)$i['player_id'],$allowed,true))throw ValidationException::withMessages(['players'=>'Playing XI players must come from the match squad.']);DB::transaction(function()use($ms,$players,$actor){PlayingXi::query()->where('match_squad_id',$ms->id)->delete();foreach($players as $i)PlayingXi::query()->create(['match_squad_id'=>$ms->id,'player_id'=>$i['player_id'],'is_captain'=>(bool)$i['is_captain'],'is_wicketkeeper'=>(bool)$i['is_wicketkeeper'],'selected_by'=>$actor]);});$this->audit->record('playing_xi.draft_saved',$actor,['match_squad_id'=>$ms->id]);return $ms->fresh(['playingXi.player']);} public function confirm(MatchSquad $ms,int $actor):MatchSquad{$this->eligibility->assertPlayingXiConfirmable($ms);$ms->update(['status'=>'Confirmed']);$this->audit->record('playing_xi.confirmed',$actor,['match_squad_id'=>$ms->id]);return $ms->fresh(['playingXi.player']);}
 public function saveBattingOrder(MatchSquad $ms,array $players,int $actor):MatchSquad{$xi=$ms->playingXi()->pluck('player_id')->map(fn($v)=>(int)$v)->sort()->values()->all();$ids=collect($players)->pluck('player_id')->map(fn($v)=>(int)$v)->sort()->values()->all();if($xi!==$ids)throw ValidationException::withMessages(['players'=>'Batting order must contain exactly the Playing XI.']);$pos=collect($players)->pluck('position')->map(fn($v)=>(int)$v)->sort()->values()->all();if($pos!==range(1,11))throw ValidationException::withMessages(['players'=>'Positions must be 1 through 11.']);DB::transaction(function()use($ms,$players){BattingOrder::query()->where('match_squad_id',$ms->id)->delete();foreach($players as $i)BattingOrder::query()->create(['match_squad_id'=>$ms->id,'player_id'=>$i['player_id'],'position'=>$i['position']]);});$this->audit->record('batting_order.updated',$actor,['match_squad_id'=>$ms->id]);return $ms->fresh(['battingOrder.player']);}
 public function saveBowlingAssignments(MatchSquad $ms,array $items,int $actor):MatchSquad{$xi=$ms->playingXi()->pluck('player_id')->map(fn($v)=>(int)$v)->all();foreach($items as $i)if(!in_array((int)$i['player_id'],$xi,true))throw ValidationException::withMessages(['assignments'=>'Bowling assignments must use Playing XI players only.']);DB::transaction(function()use($ms,$items){BowlingAssignment::query()->where('match_squad_id',$ms->id)->delete();foreach($items as $i)BowlingAssignment::query()->create(['match_squad_id'=>$ms->id,'player_id'=>$i['player_id'],'phase'=>$i['phase'],'priority'=>$i['priority']??1,'notes'=>$i['notes']??null]);});$this->audit->record('bowling_assignments.updated',$actor,['match_squad_id'=>$ms->id]);return $ms->fresh(['bowlingAssignments.player']);} }
